INSERT INTO `taq_data` VALUES (/*taq_no*/3188, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'777', /*chunk*/'天然气水合物', /*detail*/'这个是什么？', /*detail_2*/'由三个数字“7”组成。老虎机中很常见，被认为非常吉利', /*assist_detail*/'777', /*image_id*/0, /*char_no_1*/28982, /*char_no_2*/27668, /*char_no_3*/27700, /*char_no_4*/21512, /*char_no_5*/29289, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3189, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'Yourself', /*chunk*/'DIY＝自己动手做', /*detail*/'这个的全称是什么？', /*detail_2*/'', /*assist_detail*/'DIY\n=do it yourself', /*image_id*/0, /*char_no_1*/33258, /*char_no_2*/24049, /*char_no_3*/21160, /*char_no_4*/25163, /*char_no_5*/20570, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3190, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'集朱印', /*chunk*/'死神=Death', /*detail*/'这个是什么？', /*detail_2*/'收集证明参拜寺院或神社的印章。可以享受到收集印章的乐趣，逐渐很受欢迎', /*assist_detail*/'集朱印', /*image_id*/0, /*char_no_1*/68, /*char_no_2*/101, /*char_no_3*/97, /*char_no_4*/116, /*char_no_5*/104, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3191, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'战损比', /*chunk*/'高塔=The Tower', /*detail*/'这个是什么？', /*detail_2*/'游戏中，自己击倒敌人的次数和被敌人击倒的次数的比率。和“击杀率”有一点不同', /*assist_detail*/'战损比', /*image_id*/0, /*char_no_1*/84, /*char_no_2*/111, /*char_no_3*/119, /*char_no_4*/101, /*char_no_5*/114, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3192, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'露天浴池', /*chunk*/'正义=The Justice', /*detail*/'这个是什么？', /*detail_2*/'温泉的一种形式，开发在室外的浴池。作为温泉的乐趣之一深受人们喜爱', /*assist_detail*/'露天浴池', /*image_id*/0, /*char_no_1*/74, /*char_no_2*/117, /*char_no_3*/115, /*char_no_4*/116, /*char_no_5*/105, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3193, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'恵比寿天', /*chunk*/'审判=Judgement', /*detail*/'这个是什么？', /*detail_2*/'“七福神”中，掌管渔业和商业的神明。脸上笑眯眯的，拿着钓鱼竿和鲷鱼的样子很出名', /*assist_detail*/'恵比寿天（用汉字）', /*image_id*/0, /*char_no_1*/74, /*char_no_2*/117, /*char_no_3*/100, /*char_no_4*/103, /*char_no_5*/101, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3194, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'电子竞技', /*chunk*/'恋人=The Lovers', /*detail*/'这个是什么？', /*detail_2*/'数字游戏作为一项体育运动，近年来普及的称呼', /*assist_detail*/'电子竞技', /*image_id*/0, /*char_no_1*/76, /*char_no_2*/111, /*char_no_3*/118, /*char_no_4*/101, /*char_no_5*/114, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3195, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'保鲜', /*chunk*/'皇帝=The Emperor', /*detail*/'这个是什么？', /*detail_2*/'对鲜花进行特殊加工，使其不会枯萎以供观赏', /*assist_detail*/'保鲜花', /*image_id*/0, /*char_no_1*/112, /*char_no_2*/101, /*char_no_3*/114, /*char_no_4*/111, /*char_no_5*/114, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
