INSERT INTO `taq_data` VALUES (/*taq_no*/3197, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'新手', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'指在赌博等方面，新手运气特别好', /*assist_detail*/'新手运', /*image_id*/0, /*char_no_1*/26032, /*char_no_2*/25163, /*char_no_3*/30340, /*char_no_4*/24184, /*char_no_5*/36816, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3199, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'里千家', /*chunk*/'Wands', /*detail*/'这个是什么？', /*detail_2*/'被称为“三千家”的茶道三个流派，除了“表千家”和“武者小路千家”外还有一个是什么？', /*assist_detail*/'里千家', /*image_id*/0, /*char_no_1*/87, /*char_no_2*/97, /*char_no_3*/110, /*char_no_4*/100, /*char_no_5*/115, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3200, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'轮唱', /*chunk*/'0=愚者、1=魔法师', /*detail*/'这个是什么？', /*detail_2*/'青蛙之歌中熟悉的歌唱法。分成多个小组，以一定的间隔跟在后面唱歌', /*assist_detail*/'轮唱', /*image_id*/0, /*char_no_1*/24858, /*char_no_2*/32773, /*char_no_3*/39764, /*char_no_4*/27861, /*char_no_5*/24072, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3201, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'反英雄', /*chunk*/'11=正义、12=倒吊人', /*detail*/'这个是什么？', /*detail_2*/'也被称为黑暗英雄的虚构角色形象。既叛逆又有魅力', /*assist_detail*/'反英雄', /*image_id*/0, /*char_no_1*/27491, /*char_no_2*/20041, /*char_no_3*/20498, /*char_no_4*/21514, /*char_no_5*/20154, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3202, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'不看就吃', /*chunk*/'树根和地下菌', /*detail*/'这首歌的歌词是？', /*detail_2*/'著名童谣的唱段。♪收到白山羊来信的黑山羊……', /*assist_detail*/'不看就吃了', /*image_id*/0, /*char_no_1*/26641, /*char_no_2*/26681, /*char_no_3*/22320, /*char_no_4*/19979, /*char_no_5*/33740, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3204, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'赶海', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'趁着退潮的时候，在海滩上捕捉贝类和生物来玩耍。春天到来就可以享受这份乐趣了', /*assist_detail*/'赶海', /*image_id*/0, /*char_no_1*/28023, /*char_no_2*/36793, /*char_no_3*/25366, /*char_no_4*/28023, /*char_no_5*/40092, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3205, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'观赏红叶', /*chunk*/'战车=The Chariot', /*detail*/'这个是什么？', /*detail_2*/'在红叶时节前往山中看风景。并不会采摘什么东西，只是单纯地用眼欣赏', /*assist_detail*/'观赏红叶', /*image_id*/0, /*char_no_1*/67, /*char_no_2*/104, /*char_no_3*/97, /*char_no_4*/114, /*char_no_5*/105, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3206, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'福招来', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在“节分”时对鬼扔豆子要说的台词', /*assist_detail*/'鬼出去，福招来', /*image_id*/0, /*char_no_1*/28040, /*char_no_2*/21270, /*char_no_3*/24615, /*char_no_4*/27602, /*char_no_5*/28082, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3207, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'鲤鱼旗', /*chunk*/'Seven years', /*detail*/'这个是什么？', /*detail_2*/'作为季节性活动在5月5日前后装饰在外面。“♪比房顶还高～”的歌词也耳熟能详', /*assist_detail*/'鲤鱼旗', /*image_id*/0, /*char_no_1*/83, /*char_no_2*/101, /*char_no_3*/118, /*char_no_4*/101, /*char_no_5*/110, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3208, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'ground', /*chunk*/'烟雾、寄生虫', /*detail*/'这个的全称是什么？', /*detail_2*/'下雨的时候，乌鸦喜欢站在烟囱上，是为了利用□□烘干羽毛，顺便杀死□□□。', /*assist_detail*/'und=underground', /*image_id*/0, /*char_no_1*/28895, /*char_no_2*/38654, /*char_no_3*/23492, /*char_no_4*/29983, /*char_no_5*/34411, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3209, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'默剧', /*chunk*/'哑剧=Mime artist', /*detail*/'这个是什么？', /*detail_2*/'自古以来深受喜爱的街头艺人表演，表现得仿佛墙壁或楼梯真实存在般', /*assist_detail*/'默剧', /*image_id*/0, /*char_no_1*/114, /*char_no_2*/116, /*char_no_3*/105, /*char_no_4*/115, /*char_no_5*/116, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3210, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'彩菊烟花', /*chunk*/'力量=Strength', /*detail*/'这个是什么？', /*detail_2*/'一种烟花。不拿在手上，点火后丢到地面，烟花就会像某种动物一样转动并产生火花', /*assist_detail*/'彩菊烟花', /*image_id*/0, /*char_no_1*/83, /*char_no_2*/116, /*char_no_3*/114, /*char_no_4*/101, /*char_no_5*/110, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3211, /*genre*/3, /*taq_type*/2, /*difficulty*/1, /*word*/'行板', /*chunk*/'世界=The World', /*detail*/'这个是什么？', /*detail_2*/'音乐术语，指“以步行的速度”', /*assist_detail*/'行板', /*image_id*/0, /*char_no_1*/87, /*char_no_2*/111, /*char_no_3*/114, /*char_no_4*/108, /*char_no_5*/100, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
