INSERT INTO `taq_data` VALUES (/*taq_no*/3214, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'三味线', /*chunk*/'皇后=The Empress', /*detail*/'这个是什么？', /*detail_2*/'非常知名的日本乐器，是用3根弦来弹奏的弦乐器。与其非常相似的乐器有“三弦”', /*assist_detail*/'三味线', /*image_id*/0, /*char_no_1*/69, /*char_no_2*/109, /*char_no_3*/112, /*char_no_4*/114, /*char_no_5*/101, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3215, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'条纹', /*chunk*/'Tattoo', /*detail*/'这个是什么？', /*detail_2*/'指条纹图案。容易被误解成仅指纵向条纹，但其实纵向和横向都适用', /*assist_detail*/'条纹', /*image_id*/0, /*char_no_1*/84, /*char_no_2*/97, /*char_no_3*/116, /*char_no_4*/116, /*char_no_5*/111, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3216, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'环绕声效', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在家庭影院等地方将扬声器围绕着自己放置、让声音听起来很立体的装置', /*assist_detail*/'环绕声效', /*image_id*/0, /*char_no_1*/29615, /*char_no_2*/32469, /*char_no_3*/31435, /*char_no_4*/20307, /*char_no_5*/22768, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3217, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'暖色', /*chunk*/'恶魔=The Devil', /*detail*/'这个是什么？', /*detail_2*/'指红色、橙色、黄色等给人以温暖印象的色系', /*assist_detail*/'暖色系', /*image_id*/0, /*char_no_1*/68, /*char_no_2*/101, /*char_no_3*/118, /*char_no_4*/105, /*char_no_5*/108, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3218, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'遮盖', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'涂装模型或手办时，用来覆盖不想涂涂料的地方的胶带', /*assist_detail*/'遮蔽胶带', /*image_id*/0, /*char_no_1*/26149, /*char_no_2*/22825, /*char_no_3*/24555, /*char_no_4*/21040, /*char_no_5*/20102, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3219, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'极弱', /*chunk*/'常绿且树形呈三角形的松柏类树木', /*detail*/'这个是什么？', /*detail_2*/'在音乐术语中，“弱”是“piano”，“稍弱”是“mezzo piano”，那么“最弱”怎么说？', /*assist_detail*/'极弱', /*image_id*/0, /*char_no_1*/19977, /*char_no_2*/35282, /*char_no_3*/24418, /*char_no_4*/26494, /*char_no_5*/26575, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3220, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'书虫', /*chunk*/'Moonquake', /*detail*/'这个是什么？', /*detail_2*/'这个词用来形容喜欢读书的人，比喻他们像是以书为食、栖息于书中的生物', /*assist_detail*/'书虫', /*image_id*/0, /*char_no_1*/77, /*char_no_2*/111, /*char_no_3*/111, /*char_no_4*/110, /*char_no_5*/113, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/3221, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'速写画', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在中小学的美术教育中也经常见到的教学方式，要求在大约十分钟的短时间内快速画出模特', /*assist_detail*/'速写画', /*image_id*/0, /*char_no_1*/29233, /*char_no_2*/26031, /*char_no_3*/22522, /*char_no_4*/25705, /*char_no_5*/20154, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3222, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'立体主义', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'也被称为“立体派”、“立体主义”，是指一场发生在美术界的大运动', /*assist_detail*/'立体主义', /*image_id*/0, /*char_no_1*/38750, /*char_no_2*/27954, /*char_no_3*/30456, /*char_no_4*/24605, /*char_no_5*/23376, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
