INSERT INTO `taq_data` VALUES (/*taq_no*/3225, /*genre*/3, /*taq_type*/2, /*difficulty*/2, /*word*/'畜生道', /*chunk*/'人道、畜生道', /*detail*/'这个是什么？', /*detail_2*/'佛教术语中的“六道”。除了天神道、人间道、修罗道、地狱道、饿鬼道，还有一个叫什么？', /*assist_detail*/'畜生道', /*image_id*/0, /*char_no_1*/20154, /*char_no_2*/36947, /*char_no_3*/30044, /*char_no_4*/29983, /*char_no_5*/36947, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/3226, /*genre*/3, /*taq_type*/2, /*difficulty*/3, /*word*/'无边际', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'游泳池的边缘直接与大海相连，没有边界，可以无限延展的设施', /*assist_detail*/'无边际泳池', /*image_id*/0, /*char_no_1*/26080, /*char_no_2*/36793, /*char_no_3*/38469, /*char_no_4*/27891, /*char_no_5*/27744, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
