INSERT INTO `taq_data` VALUES (/*taq_no*/5148, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'葱白丝', /*chunk*/'室内健康指标', /*detail*/'这个是什么？', /*detail_2*/'把葱白部分切得和头发一样细。用于日式料理的装饰', /*assist_detail*/'葱白丝', /*image_id*/0, /*char_no_1*/20869, /*char_no_2*/20581, /*char_no_3*/24247, /*char_no_4*/25351, /*char_no_5*/26631, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5149, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'黄麻', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'因为营养价值特别高，也被称为“蔬菜之王”的绿叶蔬菜', /*assist_detail*/'黄麻', /*image_id*/0, /*char_no_1*/27700, /*char_no_2*/36164, /*char_no_3*/28304, /*char_no_4*/25351, /*char_no_5*/26631, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5150, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'思慕雪', /*chunk*/'污水与垃圾减量指标', /*detail*/'这个是什么？', /*detail_2*/'将冷冻的水果蔬菜等放入搅拌机中制作而成的饮品，常见于早餐', /*assist_detail*/'思慕雪', /*image_id*/0, /*char_no_1*/27745, /*char_no_2*/27700, /*char_no_3*/22403, /*char_no_4*/22334, /*char_no_5*/20943, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5151, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'日常', /*chunk*/'夜间例行公事', /*detail*/'这个是什么？', /*detail_2*/'指每天晚上进行的、只有自己才有的习惯。近年很流行让艺人拍摄这样的视频进行传播', /*assist_detail*/'晚间日常', /*image_id*/0, /*char_no_1*/38388, /*char_no_2*/20363, /*char_no_3*/34892, /*char_no_4*/20844, /*char_no_5*/20107, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
