INSERT INTO `taq_data` VALUES (/*taq_no*/5153, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'油炸紫菜卷', /*chunk*/'寿司、鳗鱼、荞麦面、天妇罗', /*detail*/'这个是什么？', /*detail_2*/'一种天妇罗。包裹着混有“青海苔”的面衣，将竹轮等糊状物油炸制成的食物', /*assist_detail*/'油炸紫菜卷', /*image_id*/0, /*char_no_1*/23551, /*char_no_2*/21496, /*char_no_3*/22825, /*char_no_4*/22919, /*char_no_5*/32599, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5155, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'大吉岭', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'非常流行的红茶种类。与“祁门”、“锡兰”并列，被评为“世界三大红茶”', /*assist_detail*/'大吉岭', /*image_id*/0, /*char_no_1*/22823, /*char_no_2*/21513, /*char_no_3*/23725, /*char_no_4*/32418, /*char_no_5*/33590, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
