INSERT INTO `taq_data` VALUES (/*taq_no*/5182, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'亿寓', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'出售价格超过1亿日元的特别高级的公寓的俗称', /*assist_detail*/'亿寓', /*image_id*/0, /*char_no_1*/26577, /*char_no_2*/27224, /*char_no_3*/33678, /*char_no_4*/33678, /*char_no_5*/37233, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5183, /*genre*/5, /*taq_type*/2, /*difficulty*/1, /*word*/'停车', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'高速公路上“SA”是“服务区”。那么“PA”是什么？', /*assist_detail*/'停车区', /*image_id*/0, /*char_no_1*/26368, /*char_no_2*/21491, /*char_no_3*/20391, /*char_no_4*/36710, /*char_no_5*/36947, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5185, /*genre*/5, /*taq_type*/2, /*difficulty*/1, /*word*/'汉堡牛肉', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'经典的肉类料理。以肉末为主，和鸡蛋、面包粉、蔬菜等一起揉捏后煎制', /*assist_detail*/'汉堡牛肉', /*image_id*/0, /*char_no_1*/26368, /*char_no_2*/24038, /*char_no_3*/20391, /*char_no_4*/36710, /*char_no_5*/36947, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5186, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'欢迎', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在婚礼或派对等场合，用来迎接客人而放置在入口处的指示牌', /*assist_detail*/'欢迎板', /*image_id*/0, /*char_no_1*/21516, /*char_no_2*/21521, /*char_no_3*/19977, /*char_no_4*/36710, /*char_no_5*/36947, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5188, /*genre*/5, /*taq_type*/2, /*difficulty*/1, /*word*/'青瓜海苔卷寿司', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'海苔卷寿司的一种，里面卷的是黄瓜', /*assist_detail*/'青瓜海苔卷寿司', /*image_id*/0, /*char_no_1*/23567, /*char_no_2*/40644, /*char_no_3*/29916, /*char_no_4*/23551, /*char_no_5*/21496, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5190, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'什锦寿司饭', /*chunk*/'匝道与主线车道之间', /*detail*/'这个是什么？', /*detail_2*/'一种寿司，其特征不是捏或卷，而是将食材分散放在米饭上', /*assist_detail*/'什锦寿司饭', /*image_id*/0, /*char_no_1*/21277, /*char_no_2*/36947, /*char_no_3*/20027, /*char_no_4*/32447, /*char_no_5*/36710, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5191, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'二八荞麦面', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'“荞麦面”的一种，指将荞麦粉和乌冬粉按2:8的比例擀成的荞麦面', /*assist_detail*/'二八荞麦面', /*image_id*/0, /*char_no_1*/20108, /*char_no_2*/20843, /*char_no_3*/33630, /*char_no_4*/40614, /*char_no_5*/38754, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5192, /*genre*/5, /*taq_type*/2, /*difficulty*/1, /*word*/'鲱鱼罐头', /*chunk*/'甲、乙、丙、丁、戊、己、庚……', /*detail*/'这个是什么？', /*detail_2*/'作为“世上最臭的罐头”，无论好坏都十分出名的食物。用通过盐腌制的鲱鱼制作而成', /*assist_detail*/'鲱鱼罐头', /*image_id*/0, /*char_no_1*/30002, /*char_no_2*/20057, /*char_no_3*/19993, /*char_no_4*/19969, /*char_no_5*/25098, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5193, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'子丑寅卯辰', /*chunk*/'子、丑、寅、卯、辰、巳、午、未、申……', /*detail*/'这个是什么？', /*detail_2*/'“干支”按顺序排列，最开头的5个是什么？', /*assist_detail*/'子、丑、寅、卯、辰、巳、午、未、申……', /*image_id*/0, /*char_no_1*/23376, /*char_no_2*/19985, /*char_no_3*/23493, /*char_no_4*/21359, /*char_no_5*/36784, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5194, /*genre*/5, /*taq_type*/1, /*difficulty*/1, /*word*/'不可燃垃圾', /*chunk*/'慈乐之音回忆收藏柜', /*detail*/'这个是什么？', /*detail_2*/'充满回忆的展架，摆满慈乐之音夏日演唱会的周边商品。', /*assist_detail*/'可燃垃圾⇔不可燃垃圾', /*image_id*/0, /*char_no_1*/22238, /*char_no_2*/24518, /*char_no_3*/25910, /*char_no_4*/34255, /*char_no_5*/26588, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5195, /*genre*/5, /*taq_type*/1, /*difficulty*/3, /*word*/'住宅城', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'指白天在大都市通勤，只有晚上才会回去的，在大都市近郊发展的城市', /*assist_detail*/'住宅城', /*image_id*/0, /*char_no_1*/22825, /*char_no_2*/38706, /*char_no_3*/37329, /*char_no_4*/29976, /*char_no_5*/27700, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5196, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'拼车', /*chunk*/'主线车道外侧', /*detail*/'这个是什么？', /*detail_2*/'和汽车租赁一样，是近年来迅速普及开来的租车服务。优点是短时间也可轻松使用', /*assist_detail*/'拼车', /*image_id*/0, /*char_no_1*/20027, /*char_no_2*/32447, /*char_no_3*/36710, /*char_no_4*/36947, /*char_no_5*/22806, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5197, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'烧麦', /*chunk*/'', /*detail*/'这个怎么念？', /*detail_2*/'用面皮包住搅猪肉馅后蒸熟的一种中华料理', /*assist_detail*/'烧麦=shaomai', /*image_id*/0, /*char_no_1*/39640, /*char_no_2*/20056, /*char_no_3*/36733, /*char_no_4*/36710, /*char_no_5*/36947, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5198, /*genre*/5, /*taq_type*/1, /*difficulty*/2, /*word*/'炒饭', /*chunk*/'大地仙人掌蜜汁松饼', /*detail*/'这道料理叫什么？', /*detail_2*/'称霸“沙瀑底的都城”的证明。可放置在公会之家的家具。', /*assist_detail*/'炒饭=chaofan', /*image_id*/0, /*char_no_1*/22823, /*char_no_2*/22320, /*char_no_3*/20185, /*char_no_4*/20154, /*char_no_5*/25484, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5199, /*genre*/5, /*taq_type*/2, /*difficulty*/3, /*word*/'闰年', /*chunk*/'主线车道外侧', /*detail*/'这个是什么？', /*detail_2*/'公历中，实际的季节和日历上有很小的差距，所以每4年设置一次“366天”的年份', /*assist_detail*/'闰年', /*image_id*/0, /*char_no_1*/20027, /*char_no_2*/32447, /*char_no_3*/36710, /*char_no_4*/36947, /*char_no_5*/22806, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5200, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'浴盐', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'入浴剂的一种，因为使用富含矿物质的盐类成分制成而得名', /*assist_detail*/'浴盐', /*image_id*/0, /*char_no_1*/20013, /*char_no_2*/22830, /*char_no_3*/20998, /*char_no_4*/38548, /*char_no_5*/24102, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5201, /*genre*/5, /*taq_type*/1, /*difficulty*/2, /*word*/'马铃薯', /*chunk*/'身为淑女的五条守则', /*detail*/'这个是什么？', /*detail_2*/'“土豆”的别称。一般不太常用，但在正式文本中更倾向于用这个称呼', /*assist_detail*/'马铃薯', /*image_id*/4147, /*char_no_1*/28113, /*char_no_2*/22899, /*char_no_3*/20116, /*char_no_4*/26465, /*char_no_5*/23432, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/5202, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'拍卖', /*chunk*/'Rest area', /*detail*/'这个是什么？', /*detail_2*/'买卖物品的一种方法，也被称为“竞卖”。会使用“投标”“中标”等用语', /*assist_detail*/'拍卖', /*image_id*/0, /*char_no_1*/115, /*char_no_2*/116, /*char_no_3*/114, /*char_no_4*/101, /*char_no_5*/97, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
