INSERT INTO `taq_data` VALUES (/*taq_no*/5204, /*genre*/5, /*taq_type*/2, /*difficulty*/2, /*word*/'纸币夹', /*chunk*/'Highway', /*detail*/'这个是什么？', /*detail_2*/'夹着纸币或卡，可以随身携带的用品，比起钱包更轻便，因此使用人数在增加', /*assist_detail*/'纸币夹', /*image_id*/0, /*char_no_1*/105, /*char_no_2*/103, /*char_no_3*/104, /*char_no_4*/119, /*char_no_5*/97, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/5205, /*genre*/5, /*taq_type*/2, /*difficulty*/1, /*word*/'中腹', /*chunk*/'Breakfast', /*detail*/'这个是什么？', /*detail_2*/'作为寿司材料为人熟知的金枪鱼部位。脂肪程度中等，在受人欢迎的食材中拥有绝对地位', /*assist_detail*/'中腹', /*image_id*/0, /*char_no_1*/66, /*char_no_2*/114, /*char_no_3*/101, /*char_no_4*/97, /*char_no_5*/107, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
