INSERT INTO `taq_data` VALUES (/*taq_no*/6013, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'浣熊', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'一种哺乳类动物。将手直接伸入水中获取猎物的样子看起来像在“洗东西”。', /*assist_detail*/'浣熊', /*image_id*/0, /*char_no_1*/30333, /*char_no_2*/25484, /*char_no_3*/38271, /*char_no_4*/33218, /*char_no_5*/29503, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
