INSERT INTO `taq_data` VALUES (/*taq_no*/6015, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'袋鼠', /*chunk*/'Kangaroo', /*detail*/'这个是什么？', /*detail_2*/'一种擅长跳跃的哺乳类动物。以腹袋育儿而闻名', /*assist_detail*/'袋鼠', /*image_id*/0, /*char_no_1*/75, /*char_no_2*/97, /*char_no_3*/110, /*char_no_4*/103, /*char_no_5*/97, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6022, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'小龙', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在厄尔庇斯岛发现的生物。本该叫“类龙生物”，可“祈梨”对它的称呼是？', /*assist_detail*/'小龙', /*image_id*/0, /*char_no_1*/80, /*char_no_2*/97, /*char_no_3*/110, /*char_no_4*/100, /*char_no_5*/97, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6025, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'疾风之冥姬', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'“杏奈”的别名。据说后面的两个字不是按照字面读音来读，而是读作“赫卡忒”', /*assist_detail*/'疾风之冥姬', /*image_id*/3002, /*char_no_1*/30142, /*char_no_2*/39118, /*char_no_3*/20043, /*char_no_4*/20901, /*char_no_5*/23020, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6041, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'腾特帕斯', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'活动“危险的假期！　海滨美食家公主”的首领', /*assist_detail*/'腾特帕斯', /*image_id*/2230, /*char_no_1*/30334, /*char_no_2*/22320, /*char_no_3*/24076, /*char_no_4*/30041, /*char_no_5*/32822, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6043, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'幻影', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'活动“小小的勇气·万圣节之夜！”的首领', /*assist_detail*/'幻影男爵', /*image_id*/2083, /*char_no_1*/34915, /*char_no_2*/20043, /*char_no_3*/21682, /*char_no_4*/29827, /*char_no_5*/20035, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6048, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'成熟淑女', /*chunk*/'成熟的淑女', /*detail*/'这个是什么？', /*detail_2*/'用来形容“美咲”这类女性的称呼。一般用于指出那种强装成熟的模样很可爱', /*assist_detail*/'成熟的淑女', /*image_id*/6048, /*char_no_1*/25104, /*char_no_2*/29087, /*char_no_3*/30340, /*char_no_4*/28113, /*char_no_5*/22899, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6049, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'暴龙', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'“霸王龙”的另一种称呼', /*assist_detail*/'暴龙', /*image_id*/0, /*char_no_1*/19977, /*char_no_2*/32447, /*char_no_3*/38381, /*char_no_4*/22771, /*char_no_5*/40863, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6050, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'角龙', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'以三根大角为特征的有名恐龙种类。关于这个名字的念法，其实用“三角”和“龙”来分隔是正确的', /*assist_detail*/'三角龙', /*image_id*/0, /*char_no_1*/36855, /*char_no_2*/20320, /*char_no_3*/40605, /*char_no_4*/39321, /*char_no_5*/40863, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6052, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'红树林', /*chunk*/'红树林生态系', /*detail*/'这个是什么？', /*detail_2*/'生长在热带及亚热带部分水域的植物总称，其根系形状十分独特', /*assist_detail*/'红树林', /*image_id*/0, /*char_no_1*/32418, /*char_no_2*/26641, /*char_no_3*/26519, /*char_no_4*/29983, /*char_no_5*/24577, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6054, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'脚心', /*chunk*/'僵硬性扁平足', /*detail*/'这个是什么？', /*detail_2*/'人类的足底不与地面接触的凹陷部分。也有的人没有', /*assist_detail*/'脚心', /*image_id*/0, /*char_no_1*/20725, /*char_no_2*/30828, /*char_no_3*/24615, /*char_no_4*/25153, /*char_no_5*/24179, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6056, /*genre*/6, /*taq_type*/1, /*difficulty*/3, /*word*/'独眼', /*chunk*/'独眼恶魔=One Eye Devil', /*detail*/'这个怎么念？', /*detail_2*/'在黑社会中让人闻风丧胆的“深月”的外号。没人能逃过她的那只独眼', /*assist_detail*/'独眼的红色恶魔\n=独眼恶魔', /*image_id*/6056, /*char_no_1*/68, /*char_no_2*/101, /*char_no_3*/118, /*char_no_4*/105, /*char_no_5*/108, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6057, /*genre*/6, /*taq_type*/1, /*difficulty*/3, /*word*/'收藏家', /*chunk*/'收藏家（=Collector）', /*detail*/'这个怎么念？', /*detail_2*/'“七七香”的别名。因她寻找并收集各种魔法而得名', /*assist_detail*/'收藏家', /*image_id*/6057, /*char_no_1*/101, /*char_no_2*/99, /*char_no_3*/116, /*char_no_4*/111, /*char_no_5*/114, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6058, /*genre*/6, /*taq_type*/1, /*difficulty*/3, /*word*/'变貌', /*chunk*/'喜屋武 香织', /*detail*/'这个怎么念？', /*detail_2*/'“似似花”作为“七冠”的别名。因她能变化成各种模样而得名', /*assist_detail*/'变貌大妃', /*image_id*/2268, /*char_no_1*/21916, /*char_no_2*/23627, /*char_no_3*/27494, /*char_no_4*/39321, /*char_no_5*/32455, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6059, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'只会打架的笨蛋', /*chunk*/'妮侬·朱柏尔', /*detail*/'这个是什么？', /*detail_2*/'“祈梨”对“嘉夜”生气、调侃的称呼方式', /*assist_detail*/'只会打架的肌肉笨蛋', /*image_id*/0, /*char_no_1*/22958, /*char_no_2*/20396, /*char_no_3*/26417, /*char_no_4*/26575, /*char_no_5*/23572, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6060, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'纯种', /*chunk*/'安达卢西亚马（Andalucian）', /*detail*/'这个是什么？', /*detail_2*/'经过长年累月的改良，专为赛马培育的马种。也经常用于形容家世显赫的人', /*assist_detail*/'纯种赛马', /*image_id*/0, /*char_no_1*/23433, /*char_no_2*/36798, /*char_no_3*/21346, /*char_no_4*/35199, /*char_no_5*/20122, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6061, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'藏狐', /*chunk*/'英育阿拉伯马', /*detail*/'这个是什么？', /*detail_2*/'一种狐狸。近年来，因为其冷淡且大彻大悟一般的表情，近年来颇有人气', /*assist_detail*/'藏狐', /*image_id*/0, /*char_no_1*/33521, /*char_no_2*/32946, /*char_no_3*/38463, /*char_no_4*/25289, /*char_no_5*/20271, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6062, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'空棘鱼', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'一种深海鱼。从数亿年前就保持这个姿态繁衍至今，因此被称为“活化石”', /*assist_detail*/'腔棘鱼', /*image_id*/0, /*char_no_1*/33655, /*char_no_2*/20848, /*char_no_3*/28201, /*char_no_4*/34880, /*char_no_5*/39532, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6063, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'长戟', /*chunk*/'赫克力士大兜虫', /*detail*/'这个是什么？', /*detail_2*/'作为独角仙中尺寸最大的种类，在孩子们中也拥有极高人气的昆虫', /*assist_detail*/'长戟大兜虫', /*image_id*/0, /*char_no_1*/36203, /*char_no_2*/20811, /*char_no_3*/21147, /*char_no_4*/22763, /*char_no_5*/20828, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6064, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'蚜虫', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'以前的孩子们玩耍的时候把这种虫子的体液涂在头发上，让头发变得光溜溜的，虫子的名字就来源于此', /*assist_detail*/'蚜虫', /*image_id*/0, /*char_no_1*/21322, /*char_no_2*/22278, /*char_no_3*/24418, /*char_no_4*/22836, /*char_no_5*/20896, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6065, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'泪痣', /*chunk*/'太刀洗 流夏', /*detail*/'这个是什么？', /*detail_2*/'位于眼睛下方附近的黑痣通称什么', /*assist_detail*/'泪痣', /*image_id*/0, /*char_no_1*/22826, /*char_no_2*/20992, /*char_no_3*/27927, /*char_no_4*/27969, /*char_no_5*/22799, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6066, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'银背', /*chunk*/'相信有前世的中二病患者，「疾风之冥姬」', /*detail*/'这个是什么？', /*detail_2*/'上了年纪的雄性大猩猩背上的毛变白的现象。常见于群体中的首领', /*assist_detail*/'银背', /*image_id*/3002, /*char_no_1*/30142, /*char_no_2*/39118, /*char_no_3*/20043, /*char_no_4*/20901, /*char_no_5*/23020, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6067, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'变色龙', /*chunk*/'肚子非常容易饿，充满活力的少女', /*detail*/'这个是什么？', /*detail_2*/'因能自由变化身体颜色而为人熟知的爬虫类。也比喻戏路宽的演员和声优', /*assist_detail*/'变色龙', /*image_id*/1255, /*char_no_1*/20805, /*char_no_2*/28385, /*char_no_3*/27963, /*char_no_4*/21147, /*char_no_5*/30340, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6068, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'无霸勾蜓', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'一种非常大的蜻蜓。特征是有着和“鬼”的服装相似的，黑黄相间的纹路', /*assist_detail*/'无霸勾蜓', /*image_id*/0, /*char_no_1*/32905, /*char_no_2*/39135, /*char_no_3*/24615, /*char_no_4*/26118, /*char_no_5*/34411, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6069, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'grooming', /*chunk*/'Grooming', /*detail*/'这个是什么？', /*detail_2*/'作为猫等动物的习性而广为人知的“舔毛”。用英语怎么说？', /*assist_detail*/'grooming', /*image_id*/0, /*char_no_1*/71, /*char_no_2*/114, /*char_no_3*/111, /*char_no_4*/111, /*char_no_5*/109, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6070, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'獴', /*chunk*/'魅惑众多男性的纯洁女教师', /*detail*/'这个是什么？', /*detail_2*/'一般被认为是“黄绿原矛头蝮”的天敌，是身长达数十厘米左右的哺乳类动物', /*assist_detail*/'獴', /*image_id*/0, /*char_no_1*/32431, /*char_no_2*/27905, /*char_no_3*/22899, /*char_no_4*/25945, /*char_no_5*/24072, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6071, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'碧伟蜓', /*chunk*/'觉醒了忠义之心的女商人', /*detail*/'这个是什么？', /*detail_2*/'蜻蜓的一种。身体呈黄绿色，但仔细一看上面有漂亮的银色花纹，它也因此得名', /*assist_detail*/'碧伟蜓', /*image_id*/6020, /*char_no_1*/24544, /*char_no_2*/20041, /*char_no_3*/22899, /*char_no_4*/21830, /*char_no_5*/20154, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6072, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'洋甘菊', /*chunk*/'一年生草本植物', /*detail*/'这个是什么？', /*detail_2*/'也被称为“母菊”的香草之一。有像苹果一样的香气，用它泡的茶很受欢迎', /*assist_detail*/'洋甘菊', /*image_id*/0, /*char_no_1*/19968, /*char_no_2*/24180, /*char_no_3*/29983, /*char_no_4*/33609, /*char_no_5*/26412, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6073, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'萤鱿', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'指尖大小的小乌贼。拥有能发出蓝白色光芒的体质，也常被食用', /*assist_detail*/'萤鱿', /*image_id*/0, /*char_no_1*/23567, /*char_no_2*/25159, /*char_no_3*/25169, /*char_no_4*/27969, /*char_no_5*/33828, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6074, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'金眼鲷', /*chunk*/'倒在路边的神秘猫耳魔法师', /*detail*/'这个是什么？', /*detail_2*/'作为高级鱼和吉祥物而为人熟知的一种鲷鱼。它的名字来源于它金光闪闪的眼睛', /*assist_detail*/'金眼鲷', /*image_id*/2230, /*char_no_1*/29483, /*char_no_2*/32819, /*char_no_3*/39764, /*char_no_4*/27861, /*char_no_5*/24072, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6075, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'大王具足虫', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'栖息在深海的甲壳类动物。外形与西瓜虫相似，最大的体长超过50厘米', /*assist_detail*/'大王具足虫', /*image_id*/0, /*char_no_1*/22823, /*char_no_2*/29579, /*char_no_3*/20855, /*char_no_4*/36275, /*char_no_5*/34411, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6076, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'花园鳗', /*chunk*/'花园鳗=Garden eel', /*detail*/'这个是什么？', /*detail_2*/'在水族馆里也是很受欢迎的一种海鳗。其特征是会从砂底探出身体，成群结队地朝向同一个方向', /*assist_detail*/'花园鳗', /*image_id*/0, /*char_no_1*/97, /*char_no_2*/114, /*char_no_3*/100, /*char_no_4*/101, /*char_no_5*/110, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6077, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'霸王花', /*chunk*/'肉质寄生性草本植物', /*detail*/'这个是什么？', /*detail_2*/'作为“世上最大的花”而为人熟知，生活在热带地域的花。以散发强烈恶臭而闻名', /*assist_detail*/'霸王花', /*image_id*/0, /*char_no_1*/32905, /*char_no_2*/36136, /*char_no_3*/23492, /*char_no_4*/29983, /*char_no_5*/24615, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6078, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'毒蝇蕈', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'一种有着鲜红伞盖，上面带有白点的蘑菇。有毒，吃下后会有幻觉、腹痛等症状', /*assist_detail*/'毒蝇蕈', /*image_id*/0, /*char_no_1*/27602, /*char_no_2*/34631, /*char_no_3*/40517, /*char_no_4*/33167, /*char_no_5*/33740, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6079, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'东方角鸮', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'“猫头鹰”的一种。感受到危险时，有将身体缩细，拟态成树枝的习性', /*assist_detail*/'东方角鸮', /*image_id*/0, /*char_no_1*/22812, /*char_no_2*/34892, /*char_no_3*/24615, /*char_no_4*/21160, /*char_no_5*/29289, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6080, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'蝾螈', /*chunk*/'丧失记忆的龙族少女', /*detail*/'这个是什么？', /*detail_2*/'两栖类的一种。名字的由来是其为了防御而分泌的粘液和日式料理中使用的某香料很像', /*assist_detail*/'蝾螈', /*image_id*/0, /*char_no_1*/20007, /*char_no_2*/22833, /*char_no_3*/35760, /*char_no_4*/24518, /*char_no_5*/30340, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6081, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'款冬花茎', /*chunk*/'高钙深色蔬菜', /*detail*/'这个是什么？', /*detail_2*/'“款冬”长大之前的花蕾的部分。作为春天的蔬菜，经常被用来制作天妇罗', /*assist_detail*/'款冬花茎', /*image_id*/0, /*char_no_1*/38041, /*char_no_2*/28145, /*char_no_3*/33394, /*char_no_4*/34092, /*char_no_5*/33756, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6082, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'甘蔗', /*chunk*/'Sugar cane', /*detail*/'这个是什么？', /*detail_2*/'作为砂糖原料的禾本科植物', /*assist_detail*/'甘蔗', /*image_id*/0, /*char_no_1*/83, /*char_no_2*/117, /*char_no_3*/103, /*char_no_4*/97, /*char_no_5*/114, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6083, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'不死鸟', /*chunk*/'不死鸟=Phoenix', /*detail*/'这个是什么？', /*detail_2*/'又称为凤凰，就算死了也会重生的传说中的鸟', /*assist_detail*/'不死鸟', /*image_id*/0, /*char_no_1*/80, /*char_no_2*/104, /*char_no_3*/111, /*char_no_4*/101, /*char_no_5*/110, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6084, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'嗅觉', /*chunk*/'视觉=See、听觉=Sound、触觉=Feel、味觉=Taste、嗅觉=Smell', /*detail*/'这个是什么？', /*detail_2*/'被称为“五感”的动物机能，除了视觉、听觉、触觉、味觉，还有一样是什么？', /*assist_detail*/'嗅觉', /*image_id*/0, /*char_no_1*/83, /*char_no_2*/109, /*char_no_3*/101, /*char_no_4*/108, /*char_no_5*/108, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6085, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'捶胸', /*chunk*/'高人气唱跳偶像', /*detail*/'这个是什么？', /*detail_2*/'大猩猩用手捶打胸口发出声音的行为', /*assist_detail*/'捶胸', /*image_id*/0, /*char_no_1*/39640, /*char_no_2*/20154, /*char_no_3*/27668, /*char_no_4*/21809, /*char_no_5*/36339, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6086, /*genre*/6, /*taq_type*/1, /*difficulty*/3, /*word*/'肌腱', /*chunk*/'为了保护人们而歌唱的唱唤士少女', /*detail*/'这个是什么？', /*detail_2*/'位于大腿内侧的大块肌肉群。在肌肉锻炼中也经常受到重视', /*assist_detail*/'肌腱', /*image_id*/0, /*char_no_1*/21809, /*char_no_2*/21796, /*char_no_3*/22763, /*char_no_4*/23569, /*char_no_5*/22899, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6087, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'杂食', /*chunk*/'Omnivorous', /*detail*/'这个是什么？', /*detail_2*/'吃肉的是肉食。吃植物的是草食。那么，两样都吃的是什么？', /*assist_detail*/'杂食', /*image_id*/0, /*char_no_1*/118, /*char_no_2*/111, /*char_no_3*/114, /*char_no_4*/111, /*char_no_5*/117, /*input_type_1*/3, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
