INSERT INTO `taq_data` VALUES (/*taq_no*/6174, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'座敷童子', /*chunk*/'Carnation', /*detail*/'这个是什么？', /*detail_2*/'以小孩子的模样出现在屋内的妖怪。据说遇到它的人会变得好运。', /*assist_detail*/'座敷童子', /*image_id*/0, /*char_no_1*/67, /*char_no_2*/97, /*char_no_3*/114, /*char_no_4*/110, /*char_no_5*/97, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
