INSERT INTO `taq_data` VALUES (/*taq_no*/6176, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'杜拉汉', /*chunk*/'我比任何人都美', /*detail*/'这个是什么？', /*detail_2*/'传说中登场的无头骑士', /*assist_detail*/'杜拉汉', /*image_id*/6234, /*char_no_1*/20219, /*char_no_2*/20309, /*char_no_3*/20154, /*char_no_4*/37117, /*char_no_5*/32654, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6177, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'异瞳', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'两只眼睛的颜色各不相同。很多动物都有，尤其是猫', /*assist_detail*/'异瞳', /*image_id*/0, /*char_no_1*/32654, /*char_no_2*/22269, /*char_no_3*/22823, /*char_no_4*/23665, /*char_no_5*/29483, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6178, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'狗尾草', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'“狗尾草”的通称。在猫咪面前晃动会引起它的兴趣并令其撒欢', /*assist_detail*/'狗尾草', /*image_id*/0, /*char_no_1*/33521, /*char_no_2*/22269, /*char_no_3*/30701, /*char_no_4*/27611, /*char_no_5*/29483, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6179, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'德古拉', /*chunk*/'吸血鬼德古拉', /*detail*/'这个是什么？', /*detail_2*/'非常著名的怪物。特征是它会吸食猎物的血，弱点是十字架和大蒜', /*assist_detail*/'德古拉', /*image_id*/0, /*char_no_1*/21560, /*char_no_2*/34880, /*char_no_3*/24503, /*char_no_4*/21476, /*char_no_5*/25289, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6180, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'蜣螂', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'拥有将动物的粪便滚来滚去做成球的习性的昆虫', /*assist_detail*/'蜣螂', /*image_id*/0, /*char_no_1*/35199, /*char_no_2*/20271, /*char_no_3*/21033, /*char_no_4*/20122, /*char_no_5*/29483, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6181, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'布偶猫', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'一种猫的种类，名字有“玩偶”的意思。因为它喜欢抱抱，而且毛发蓬松柔软', /*assist_detail*/'布偶猫', /*image_id*/0, /*char_no_1*/26031, /*char_no_2*/33452, /*char_no_3*/20811, /*char_no_4*/26031, /*char_no_5*/29483, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6182, /*genre*/6, /*taq_type*/2, /*difficulty*/3, /*word*/'异国', /*chunk*/'异国短毛猫', /*detail*/'这个是什么？', /*detail_2*/'猫的一种。特点是鼻子很扁，而且看起来仿佛总板着脸般可爱', /*assist_detail*/'异国短毛猫', /*image_id*/0, /*char_no_1*/24322, /*char_no_2*/22269, /*char_no_3*/30701, /*char_no_4*/27611, /*char_no_5*/29483, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6183, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'信鸽', /*chunk*/'和平=Peace', /*detail*/'这个是什么？', /*detail_2*/'利用鸽子的归巢本能送信。通信技术还不发达的时候，广泛被利用', /*assist_detail*/'信鸽', /*image_id*/0, /*char_no_1*/80, /*char_no_2*/101, /*char_no_3*/97, /*char_no_4*/99, /*char_no_5*/101, /*input_type_1*/2, /*input_type_2*/3, /*input_type_3*/3, /*input_type_4*/3, /*input_type_5*/3);
INSERT INTO `taq_data` VALUES (/*taq_no*/6184, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'叽叽喳喳', /*chunk*/'大大咧咧、重情义的女孩', /*detail*/'这个是什么？', /*detail_2*/'表现“黄莺”啼鸣的文字。也象征着春天的到来而为人熟知', /*assist_detail*/'叽叽喳喳', /*image_id*/1262, /*char_no_1*/37325, /*char_no_2*/24773, /*char_no_3*/20041, /*char_no_4*/22899, /*char_no_5*/23401, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6185, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'小杜鹃', /*chunk*/'头脑清晰的美少女名侦探', /*detail*/'这个是什么？', /*detail_2*/'比喻武将性格的俳句“～～不肯啼，杀之可矣”中所使用的鸟类名字是什么？', /*assist_detail*/'小杜鹃', /*image_id*/0, /*char_no_1*/23569, /*char_no_2*/22899, /*char_no_3*/21517, /*char_no_4*/20390, /*char_no_5*/25506, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6186, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'蛇莓', /*chunk*/'使大家展露笑容的搞笑牧场主', /*detail*/'这个是什么？', /*detail_2*/'名字来源于它“生长在可能会有蛇的地方”，和草莓很相像的植物。但不适合食用', /*assist_detail*/'蛇莓', /*image_id*/0, /*char_no_1*/25630, /*char_no_2*/31505, /*char_no_3*/29287, /*char_no_4*/22330, /*char_no_5*/20027, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6187, /*genre*/6, /*taq_type*/1, /*difficulty*/2, /*word*/'松果', /*chunk*/'冷酷，对凡事都很直率的剑士', /*detail*/'这个是什么？', /*detail_2*/'也被称为松塔，简单来说算是松树果实的部分。常用于装饰圣诞树', /*assist_detail*/'松果', /*image_id*/0, /*char_no_1*/30452, /*char_no_2*/29575, /*char_no_3*/30340, /*char_no_4*/21073, /*char_no_5*/22763, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6188, /*genre*/6, /*taq_type*/1, /*difficulty*/1, /*word*/'阿索尔德', /*chunk*/'充满少女心的毛茸茸小动物', /*detail*/'这个角色的名字是？', /*detail_2*/'「莉玛」的角色介绍词。', /*assist_detail*/'阿索尔德', /*image_id*/4147, /*char_no_1*/20805, /*char_no_2*/28385, /*char_no_3*/23569, /*char_no_4*/22899, /*char_no_5*/24515, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
