INSERT INTO `taq_data` VALUES (/*taq_no*/6242, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'扶桑花', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'作为热带地区的象征花，在香织的故乡也很受欢迎。有着红色或黄色鲜艳花瓣', /*assist_detail*/'扶桑花', /*image_id*/0, /*char_no_1*/31859, /*char_no_2*/24320, /*char_no_3*/26391, /*char_no_4*/22522, /*char_no_5*/32599, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
