INSERT INTO `taq_data` VALUES (/*taq_no*/6244, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'锦鲤', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'在“鲤鱼”中也属于常被用作观赏的品种，因为与高级织物的花纹很相似而得名', /*assist_detail*/'锦鲤', /*image_id*/0, /*char_no_1*/26612, /*char_no_2*/21487, /*char_no_3*/22827, /*char_no_4*/26031, /*char_no_5*/22522, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
