INSERT INTO `taq_data` VALUES (/*taq_no*/6246, /*genre*/6, /*taq_type*/2, /*difficulty*/2, /*word*/'蟒蛇', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'蛇的一种，体型大的可达数米。常在电影中被描绘成恐怖的蛇', /*assist_detail*/'蟒蛇', /*image_id*/0, /*char_no_1*/24343, /*char_no_2*/26391, /*char_no_3*/35199, /*char_no_4*/26031, /*char_no_5*/31185, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
INSERT INTO `taq_data` VALUES (/*taq_no*/6247, /*genre*/6, /*taq_type*/2, /*difficulty*/1, /*word*/'塔兰图拉', /*chunk*/'', /*detail*/'这个是什么？', /*detail_2*/'作为“毒蜘蛛的代名词”而广为人知的大型蜘蛛。但也有很多人喜欢养来当宠物', /*assist_detail*/'塔兰图拉毒蛛', /*image_id*/0, /*char_no_1*/24449, /*char_no_2*/26381, /*char_no_3*/32773, /*char_no_4*/23041, /*char_no_5*/24265, /*input_type_1*/6, /*input_type_2*/6, /*input_type_3*/6, /*input_type_4*/6, /*input_type_5*/6);
